/**
 * The generator for accessing doubles
 * 
 * <p>
 * This is accomplished by delegating to the long access generator with type conversion.
 */
public class DoubleAccessGen : SimpleAccessGen<TDouble, DoubleJitType>
{	public static readonly DoubleAccessGen BE = new(LongAccessGen.BE);
	public static readonly DoubleAccessGen LE = new(LongAccessGen.LE);


	LongAccessGen longGen;

	private DoubleAccessGen(LongAccessGen longGen) {
		this.longGen = longGen;
	}

	/* @Override */
	public  genReadToStack<THIS, N>/* where THIS : JitCompiledPassage where N : Next> Emitter<Ent<N, TDouble> */(Emitter<N> em, Local<TRef<THIS>> localThis, JitCodeGenerator<THIS> gen,
					Varnode vn) {
		return em
				.emit(longGen.genReadToStack, localThis, gen, vn)
				.emit(LongToDouble.INSTANCE.convertStackToStack, LongJitType.I8, DoubleJitType.F8,
					Ext.ZERO);
	}

	/* @Override */
	public Emitter<N1> genWriteFromStack<THIS, N1, N0>/* where THIS : JitCompiledPassage where N1 : Next where N0 : Ent<N1, TDouble> */(Emitter<N0> em, Local<TRef<THIS>> localThis,
					JitCodeGenerator<THIS> gen, Varnode vn) {
		return em
				.emit(DoubleToLong.INSTANCE.convertStackToStack, DoubleJitType.F8, LongJitType.I8,
					Ext.ZERO)
				.emit(longGen.genWriteFromStack, localThis, gen, vn);
	}
}
